import { Container, Nav, Navbar, NavDropdown, Button } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";
import { LinkContainer } from "react-router-bootstrap";
import { logout, setLanguage } from "../actions/userActions";

import ButtonGroup from "react-bootstrap/ButtonGroup";
import Dropdown from "react-bootstrap/Dropdown";
import DropdownButton from "react-bootstrap/DropdownButton";
import { useState } from "react";
import "./MobileSidebar.css";

function Header() {
  const userLogin = useSelector((state) => state.userLogin);
  const { userInfo } = userLogin;
  const [menuOpen, setMenuOpen] = useState(false);

  const dispatch = useDispatch();

  const logoutHandler = () => {
    dispatch(logout());
  };

  const { i18n } = useTranslation();
  const currentLanguage = i18n.language;

  const { t } = useTranslation();

  const headerLinks = [
    { href: "#TODO", label: t("header.tobacco") },
    { href: "#TODO", label: t("header.coals") },
    { href: "#TODO", label: t("header.temperatureControl") },
    { href: "#TODO", label: t("header.glass") },
    { href: "#TODO", label: t("header.accessories") },
    { href: "#TODO", label: t("header.offers") },
  ];

  return (
    <header>
      <Navbar
        bg="light"
        variant="light"
        expand="lg"
        className="py-0 border-0"
        collapseOnSelect
      >
        <Container fluid>
          <LinkContainer to="/">
            <Navbar.Brand className="py-0">
              <img
                className="mr-3"
                style={{ transform: "scale(1.55)" }}
                src={`${process.env.PUBLIC_URL}/images/oblako.png`}
                width={150}
                alt="Oblako Logo"
              />
            </Navbar.Brand>
          </LinkContainer>

          <Navbar.Toggle
            aria-controls="mobile-sidebar"
            onClick={() => setMenuOpen(!menuOpen)}
          />

          {/* Backdrop Overlay */}
          <div
            className={`sidebar-backdrop d-lg-block ${menuOpen ? "show" : ""}`}
            onClick={() => setMenuOpen(false)}
          />

          <div
            className={`mobile-sidebar d-flex flex-column flex-lg-row justify-content-lg-between w-100 ${
              menuOpen ? "open" : ""
            }`}
          >
            <Button
              variant="link"
              className="close-button d-lg-none"
              onClick={() => setMenuOpen(false)}
            >
              ✕
            </Button>
            <Nav>
              <NavDropdown
                title={t("header.hookah")}
                id="collasible-nav-dropdown"
              >
                <NavDropdown.Item active={false} href="#TODO">
                  {t("header.lowBudget")}
                </NavDropdown.Item>
                <NavDropdown.Item active={false} href="#TODO">
                  LUXURY
                </NavDropdown.Item>
              </NavDropdown>
              {headerLinks.map((link) => (
                <Nav.Link
                  key={link.label}
                  href={link.href}
                  onClick={() => setMenuOpen(false)}
                >
                  {link.label}
                </Nav.Link>
              ))}
            </Nav>

            <Nav>
              <DropdownButton
                as={ButtonGroup}
                variant="secondary"
                title={currentLanguage.toUpperCase()}
                className="d-inline-block"
              >
                {["el", "en"].map((lang, i) => (
                  <Dropdown.Item
                    eventKey={i}
                    onClick={() => {
                      dispatch(setLanguage(lang));
                      localStorage.setItem("userLanguage", lang);
                    }}
                    active={lang === currentLanguage ? true : undefined}
                  >
                    {lang.toUpperCase()}
                  </Dropdown.Item>
                ))}
              </DropdownButton>
              <LinkContainer to="/cart" className="mt-1 mt-lg-0">
                <Nav.Link onClick={() => setMenuOpen(false)}>
                  <i className="fas fa-shopping-cart mr-2 fa-lg"></i>
                  {t("header.cart")}
                </Nav.Link>
              </LinkContainer>
              {userInfo ? (
                <NavDropdown title={userInfo.name} id="username">
                  <LinkContainer to="/profile">
                    <NavDropdown.Item>{t("header.profile")}</NavDropdown.Item>
                  </LinkContainer>

                  <NavDropdown.Item onClick={logoutHandler}>
                    {t("header.logOut")}
                  </NavDropdown.Item>
                </NavDropdown>
              ) : (
                <LinkContainer to="/login">
                  <Nav.Link onClick={() => setMenuOpen(false)}>
                    <i className="fas fa-user mr-2 fa-lg"></i>
                    {t("header.signIn")}
                  </Nav.Link>
                </LinkContainer>
              )}
              {userInfo && userInfo.isAdmin && (
                <NavDropdown title="Admin" id="adminmenue">
                  <LinkContainer to="/admin/userlist">
                    <NavDropdown.Item>{t("header.users")}</NavDropdown.Item>
                  </LinkContainer>

                  <LinkContainer to="/admin/productlist">
                    <NavDropdown.Item>{t("header.products")}</NavDropdown.Item>
                  </LinkContainer>

                  <LinkContainer to="/admin/orderlist">
                    <NavDropdown.Item>{t("header.orders")}</NavDropdown.Item>
                  </LinkContainer>
                </NavDropdown>
              )}
            </Nav>
          </div>
        </Container>
      </Navbar>
    </header>
  );
}

export default Header;
